41	/// Runs memory phase 2 (aka consolidation) in strict order. The method represents the linear
42	/// flow of the consolidation phase.
43	pub(super) async fn run(session: &Arc<Session>, config: Arc<Config>) {
44	    let phase_two_e2e_timer = session
45	        .services
46	        .otel_manager
47	        .start_timer(metrics::MEMORY_PHASE_TWO_E2E_MS, &[])
48	        .ok();
49	
50	    let Some(db) = session.services.state_db.as_deref() else {
51	        // This should not happen.
52	        return;
53	    };
54	    let root = memory_root(&config.codex_home);
55	    let max_raw_memories = config.memories.max_raw_memories_for_global;
56	
57	    // 1. Claim the job.
58	    let claim = match job::claim(session, db).await {
59	        Ok(claim) => claim,
60	        Err(e) => {
61	            session.services.otel_manager.counter(
62	                metrics::MEMORY_PHASE_TWO_JOBS,
63	                1,
64	                &[("status", e)],
65	            );
66	            return;
67	        }
68	    };
69	
70	    // 2. Get the config for the agent
71	    let Some(agent_config) = agent::get_config(config.clone()) else {
72	        // If we can't get the config, we can't consolidate.
73	        tracing::error!("failed to get agent config");
74	        job::failed(session, db, &claim, "failed_sandbox_policy").await;
75	        return;
76	    };
77	
78	    // 3. Query the memories
79	    let selection = match db.get_phase2_input_selection(max_raw_memories).await {
80	        Ok(selection) => selection,
81	        Err(err) => {
82	            tracing::error!("failed to list stage1 outputs from global: {}", err);
83	            job::failed(session, db, &claim, "failed_load_stage1_outputs").await;
84	            return;
85	        }
86	    };
87	    let raw_memories = selection.selected.to_vec();
88	    let artifact_memories = artifact_memories_for_phase2(&selection);
89	    let new_watermark = get_watermark(claim.watermark, &raw_memories);
90	
91	    // 4. Update the file system by syncing the raw memories with the one extracted from DB at
92	    //    step 3
93	    // [`rollout_summaries/`]
94	    if let Err(err) =
95	        sync_rollout_summaries_from_memories(&root, &artifact_memories, artifact_memories.len())
96	            .await
97	    {
98	        tracing::error!("failed syncing local memory artifacts for global consolidation: {err}");
99	        job::failed(session, db, &claim, "failed_sync_artifacts").await;
100	        return;
101	    }
102	    // [`raw_memories.md`]
103	    if let Err(err) =
104	        rebuild_raw_memories_file_from_memories(&root, &artifact_memories, artifact_memories.len())
105	            .await
106	    {
107	        tracing::error!("failed syncing local memory artifacts for global consolidation: {err}");
108	        job::failed(session, db, &claim, "failed_rebuild_raw_memories").await;
109	        return;
110	    }
111	    if raw_memories.is_empty() {
112	        // We check only after sync of the file system.
113	        job::succeed(
114	            session,
115	            db,
116	            &claim,
117	            new_watermark,
118	            &[],
119	            "succeeded_no_input",
120	        )
121	        .await;
122	        return;
123	    }
124	
125	    // 5. Spawn the agent
126	    let prompt = agent::get_prompt(config, &selection);
127	    let source = SessionSource::SubAgent(SubAgentSource::MemoryConsolidation);
128	    let thread_id = match session
129	        .services
130	        .agent_control
131	        .spawn_agent(agent_config, prompt, Some(source))
132	        .await
133	    {
134	        Ok(thread_id) => thread_id,
135	        Err(err) => {
136	            tracing::error!("failed to spawn global memory consolidation agent: {err}");
137	            job::failed(session, db, &claim, "failed_spawn_agent").await;
138	            return;
139	        }
140	    };

